// iam role that trusts a github repo to assume it as part of an OIDC flow
resource "aws_iam_role" "trust-me" {
  name = "t_rodman"
  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRoleWithWebIdentity",
      "Principal": {
        "Federated": "arn:aws:iam::${var.account_id}:oidc-provider/token.actions.githubusercontent.com"
      },
      "Condition": {
        "StringLike": {
                    "token.actions.githubusercontent.com:aud": "sts.amazonaws.com",
                    "token.actions.githubusercontent.com:sub": "repo:${var.github_repo}:*"
                }
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
EOF
}


// create an identity provider for the github OIDC flow
resource "aws_iam_openid_connect_provider" "github" {
  client_id_list = ["sts.amazonaws.com"]
  thumbprint_list = ["6938fd4d98bab03faadb97b34396831e3780aea1", "1c58a3a8518e8759bf075b76b750d4f2df264fcd"]
  url = "https://token.actions.githubusercontent.com"
}

// create a ssm parameter to store the flag for this challenge 
resource "aws_ssm_parameter" "trust-me-flag" {
  name = "trust-me"
  type = "SecureString"
  value = "FLAG{trustMe::the_lines_have_been_blurred}"
  overwrite = true
}

// create a policy to allow the github OIDC role to read the flag
resource "aws_iam_policy" "trust-me" {
  name = "trust-me"
  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowReadFlag",
      "Effect": "Allow",
      "Action": [
        "ssm:GetParameter"
      ],
      "Resource": [
        "arn:aws:ssm:${var.AWS_REGION}:${var.account_id}:parameter/trust-*"
      ]
    }   
  ]
}
EOF
}

// attach the policy to the github OIDC role
resource "aws_iam_role_policy_attachment" "trust-me" {
  role = aws_iam_role.trust-me.name
  policy_arn = aws_iam_policy.trust-me.arn
}

resource "aws_ssm_parameter" "trust-him" {
  name = "trust-him"
  type = "String"
  value = "not_the_flag"
  overwrite = true
}

resource "aws_ssm_parameter" "trust-her" {
  name = "trust-her"
  type = "SecureString"
  value = "not_the_flag"
  overwrite = true
}

resource "aws_ssm_parameter" "trust-them" {
  name = "trust-them"
  type = "String"
  value = "not_the_flag"
  overwrite = true
}

variable "aws_local_profile" {
  description = "What local profile should terraform use to interact with your AWS account(s)"
  type        = string
  default     = "default"
}

variable "aws_local_creds_file" {
  description = "Location of your local credentials file"
  type        = string
  default     = "~/.aws/credentials"
}

variable "aws_assume_role_arn" {
  description = "This is the arn of an already existing principal that can assume into any roles that are created"
  type        = string
  default     = ""
}

variable "account_id" {
  description = "This is the ID of the caller account"
  type        = string
  default     = ""
}


variable "shared_high_priv_servicerole" {
  description = "This is the arn of high priv service role that is attached to lambda's ec2's, etc. to facilitate privesc"
  type        = string
  default     = ""
}

variable "AWS_REGION" {
  type    = string
  default = "us-west-2"
}

# Resources
resource "random_password" "database-secret" {
  length           = 31
  special          = true
  min_special      = 5
  override_special = "!#$%^&*()-_=+[]{}<>:?"
  keepers = {
    pass_version = 1
  }
}

resource "random_password" "app-secret" {
  length           = 31
  special          = true
  min_special      = 5
  override_special = "!#$%^&*()-_=+[]{}<>:?"
  keepers = {
    pass_version = 1
  }
}

resource "random_string" "resource-suffix" {
  length           = 5 
  upper = false 
  special = false
}

variable "user_ip" {
  description = "The current user's IP address"
  type        = string
  default     = ""
}

variable "github_repo" {
  description = "The github repo for the OIDC-GitHub challenge"
  type        = string
  default     = null
}
